/// <summary>
/// Helper class for Price data extract process
/// MPJ_24248 Pricing Data Extract DCP 28/07/2024
/// </summary>
public class METPriceDataFeedHelper
{
}

Method.Source:
    /// <summary>
    /// Clean up records in working tables. Cleanup is required is a batch task terminates abnormally.
    /// Copied from GUPPriceReportGenerateEngine.deleteFindPriceTasks()
    /// </summary>
    /// <param name = "_taskGuid">Task Guid</param>
    /// <param name = "_secondConnection">User connection</param>
    public static void cleanUp(GUID _taskGuid, UserConnection  _secondConnection)
    {
        GUPriceReportItemTask                   priceReportItemTask;
        GUPriceReportItemTaskWithDimensions     findPriceTaskWithDimensions;
        GUPTmpPriceReportValues                 tmpPriceReportValues;

        if (_secondConnection)
        {
            priceReportItemTask.setConnection(_secondConnection);
            findPriceTaskWithDimensions.setConnection(_secondConnection);
            tmpPriceReportValues.setConnection(_secondConnection);
        }

        if (_taskGuid)
        {
            ttsbegin;

            delete_from priceReportItemTask where priceReportItemTask.SessionGuid == _taskGuid;
            delete_from findPriceTaskWithDimensions where findPriceTaskWithDimensions.SessionGuid == _taskGuid;
            delete_from tmpPriceReportValues where tmpPriceReportValues.ReportId == _taskGuid;

            ttscommit;
        }
    }
